  it("empty grid stays empty -- [] → []", () => {
    expect(nextGeneration([])).toEqual([]);
  });
  it("single live cell dies from underpopulation -- [(0,0)] → []", () => {
    expect(nextGeneration([[0, 0]])).toEqual([]);
  });
  it(
    "two adjacent live cells die from underpopulation (Rule 1) -- [(0,1), (1,1)] → []",
    () => {
      expect(
        nextGeneration([
          [0, 1],
          [1, 1],
