      expect(result).toEqual(
        expect.arrayContaining([
          [0, 0],
          [1, 0],
          [0, 1],
          [1, 1],
        ])
      );
      expect(result).toHaveLength(4);
    }
  );
  it(
    "live cell with 2 neighbors survives (Rule 2) -- [(0,0), (1,0), (2,0), (1,2)] → [(1,0), (0,1), (2,1)]",
    () => {
      const result = nextGeneration([
        [0, 0],
        [1, 0],
        [2, 0],
        [1, 2],
      ]);
      expect(result).toEqual(
        expect.arrayContaining([
