  const isLive = live.has(k);
  if ((isLive && (n===2||n===3)) || (!isLive && n===3)) {
    next.push(k.split(",").map(Number));
  }
}
console.log(JSON.stringify(next));
console.log("center (1,1) neighbors:", counts.get("1,1"));
'

