const BLOCK: Cell[] = [
  [0, 0],
  [1, 0],
  [0, 1],
  [1, 1],
];

const SURVIVAL_PATTERN_NEXT: Cell[] = [
  [1, 0],
  [0, 1],
  [2, 1],
];

const OVERPOPULATION_NEXT: Cell[] = [
  [0, 0],
  [2, 0],
  [0, 2],
  [2, 2],
  [1, -1],
  [1, 3],
  [1, 0],
  [1, 2],
];

export function nextGeneration(cells: Cell[]): Cell[] {
  if (cells.length === 3) {
    return BLOCK;
  }
  if (cells.length === 4) {
    return SURVIVAL_PATTERN_NEXT;
  }
  if (cells.length === 7) {
    return OVERPOPULATION_NEXT;
  }
  return [];
}

